  "home.bundle.row5.title": "ಪೂರ್ಣ ಸಸ್ಯದ ಡೇಟಾಬೇಸ್",
  "home.bundle.row5.sub": "ಪಾಲನೆ ಮಾರ್ಗದರ್ಶಿಗಳು, ಗೆಳೆಯರು, 58 ಭಾಷೆಗಳಿಗೆ ಕಾರ್ಯಾಚರಣೆ ಭಾಷಾಂತರ",
  "home.bundle.best_value": "ಅತ್ಯುತ್ತಮ ಮೌಲ್ಯ",
