  "home.bundle.lifetime_blurb": "ಮೂರು ವರ್ಷಗಳಲ್ಲಿ ವಾರ್ಷಿಕ ಪಂಗಡಕ್ಕೆ ಸಮಾನ ಪ್ರಮಾಣದಲ್ಲಿದೆ. ಅದಕ್ಕೆ ನಂತರ, ಪ್ರತಿಯೊಂದು ಋತು ಉಚಿತವಾಗಿದೆ — ನಿಮ್ಮ 2031ಸಾಲಿನ ತೋಟ ಇನ್ನೂ ಅನ್ಲಾಕ್ ಮಾಡಿದವು.",
  "home.bundle.unlock_lifetime": "ಜೀವನಕ್ಕಾಗಿ ಅನ್ಲಾಕ್ ಮಾಡಿ",
  "home.bundle.from_monthly": "ಅಥವಾ £2.99 / ತಿಂಗಳಿಗೆ →",
  "home.bundle.guarantee": "30-ದಿನಗಳ ಹಣ ತಿರುಗಿಸುವ ಉಭಯ. ಯಾವುದೇ ಚಂದಾ, ಯಾವುದೇ ಆಟೋ-ರ್ನ್ಯೂವಲ್, ಯಾವುದೇ ಇಮೇಲ್ ಪಟ್ಟಿಗಳು ಇಲ್ಲ.",
  "share_patch.button": "ನನ್ನ ಪ್ಯಾಚ್ ಅನ್ನು ಹಂಚಿಕೊಳ್ಳಿ",
  "share_patch.eyebrow": "ನನ್ನ ಪ್ಯಾಚ್ ಅನ್ನು ಹಂಚಿಕೊಳ್ಳಿ",
